import { interpolate } from './interpolate';

export type Language = 'en' | 'ar';

export interface Translations {
  [key: string]: {
    en: string;
    ar: string;
  };
}

export type TVars = Record<string, string | number>;

export function translate(
  key: string,
  language: Language,
  vars?: TVars,
  fallback?: string
): string {
  const entry = TRANSLATIONS[key];
  const interpolateIfVars = (text: string) => (vars ? interpolate(text, vars) : text);
  if (entry && entry[language]) return interpolateIfVars(entry[language]);
  if (entry) return interpolateIfVars(entry.en);
  if (import.meta.env.DEV) console.warn(`[i18n] missing translation key: ${key}`);
  return fallback ?? key;
}

