  "dahabBullet2": { en: "Fresh Red Sea catch is picked at the ice counter — grab it yourself or have the restaurant do it.", ar: "السي فود الطازج بيتم اختياره من تلج السمك — اختار صيدك بنفسك أو اطلبه من المطعم." },
